function h(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function normalizeUrl(u){ u = String(u==null?'':u).trim(); if (!u) return u; if (/^(https?:)?\/\//i.test(u)) return u.replace(/^\/\//,'https://'); if (/^(mailto:|tel:|data:|#|\/)/i.test(u)) return u; return 'https://'+u; }
function looksLikeUrl(u){ return /^(https?:\/\/[^\s]+\.[a-z]{2,}([\/:?#].*)?|mailto:[^\s]+@[^\s]+|tel:[^\s]+|data:[^\s]+)$/i.test(u||''); }

function toast(msg){
  var t = document.createElement('div');
  t.className = 'toast'; t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(function(){ t.classList.add('show'); }, 10);
  setTimeout(function(){ t.classList.remove('show'); setTimeout(function(){ t.remove(); }, 300); }, 2600);
}

