function splitContentPages(content, maxLen){
  var raw = content||'';
  if (!raw) return [''];
  var html = looksHtml(raw) ? raw : h(raw).replace(/\n/g,'<br>');
  var blocks = html.split(/(?:<br\s*\/?>\s*){2,}/i).filter(function(b){ return b && b.trim(); });
  if (!blocks.length) blocks = [html];
  function visualLen(s){
    var imgCount = (s.match(/<img[^>]*>/g)||[]).length;
    var textLen = s.replace(/<[^>]+>/g,'').length;
    return textLen + imgCount*480;
  }
  var pages = []; var cur = '';
  blocks.forEach(function(b){
    var curLen = visualLen(cur);
    var bLen = visualLen(b);
    if (cur && (curLen + bLen) > maxLen){ pages.push(cur); cur = b; }
    else cur = cur ? (cur + '<br><br>' + b) : b;
    if (visualLen(cur) > maxLen*1.4 && /<img[^>]*>/.test(cur)){ pages.push(cur); cur=''; }
  });
  if (cur) pages.push(cur);
  return pages.length ? pages : [html];
}
function buildFlipbookPages(titulo, subtitulo, content, trecho, equip, manuais, images, extras){
  var pages = [];
  var coverImg = (images && images[0]) ? images[0] : null;
  pages.push('<div class="fp-page fp-cover"'+(coverImg?' style="background-image:linear-gradient(0deg,rgba(0,0,0,.55),rgba(0,0,0,.25)),url(\''+coverImg.url.replace(/'/g,"%27")+'\')"':'')+'><h2>'+h(subtitulo||'')+'</h2><h1>'+h(titulo||'')+'</h1></div>');
  var extraImages = (images||[]).slice(1);
  var imgIdx = 0;
  var corpo = splitContentPages(content||'', 1e9).join('<br><br>');
  if (window.FPL && corpo){
    var imgHtml = '';
    if (extraImages.length){ var im0 = extraImages[imgIdx++]; imgHtml = '<div class="fp-img-wrap"><img src="'+h(im0.url)+'" alt="'+h(im0.alt||'')+'"></div>'; }
    pages.push('<div class="fp-page'+(imgHtml?' fp-page-img':'')+'">'+imgHtml+'<div class="fp-text">'+corpo+'</div></div>');
  } else splitContentPages(content||'', 620).forEach(function(chunk, i){
    var imgHtml = '';
    if (imgIdx < extraImages.length && (i%2===1)){
      var im = extraImages[imgIdx++];
      imgHtml = '<div class="fp-img-wrap"><img src="'+h(im.url)+'" alt="'+h(im.alt||'')+'"></div>';
    }
    pages.push('<div class="fp-page'+(imgHtml?' fp-page-img':'')+'">'+imgHtml+'<div class="fp-text">'+chunk+'</div></div>');
  });
  while (imgIdx < extraImages.length){
    var im2 = extraImages[imgIdx++];
    pages.push('<div class="fp-page fp-page-full-img"><img src="'+h(im2.url)+'" alt="'+h(im2.alt||'')+'"></div>');
  }
  function chunkList(arr, size){ var out=[]; for (var i=0;i<arr.length;i+=size) out.push(arr.slice(i,i+size)); return out; }
  if (trecho){
    (window.FPL ? [splitContentPages(trecho, 1e9).join('<br><br>')] : splitContentPages(trecho, 560)).forEach(function(chunk){ pages.push('<div class="fp-page fp-cover"><h3>Trecho normativo</h3><blockquote>'+chunk+'</blockquote></div>'); });
  }
  if (equip && equip.length){
    chunkList(equip, 6).forEach(function(group){ pages.push('<div class="fp-page"><h3>Equipamentos</h3><ul>'+group.map(function(e){ return '<li>'+h(e)+'</li>'; }).join('')+'</ul></div>'); });
  }
  if (manuais && manuais.length){
    chunkList(manuais, 6).forEach(function(group){ pages.push('<div class="fp-page"><h3>Manuais</h3><ul>'+group.map(function(m){ return '<li>'+h(m.nome)+'</li>'; }).join('')+'</ul></div>'); });
  }
  if (extras){
    if (extras.videos && extras.videos.length) chunkList(extras.videos, 6).forEach(function(group){ pages.push('<div class="fp-page"><h3>Vídeos</h3><ul>'+group.map(function(v){ return '<li><a href="'+h(v.url)+'" target="_blank" rel="noopener">'+h(v.titulo||v.url)+'</a></li>'; }).join('')+'</ul></div>'); });
    if (extras.links && extras.links.length) chunkList(extras.links, 6).forEach(function(group){ pages.push('<div class="fp-page"><h3>Reportagens e links</h3><ul>'+group.map(function(l){ return '<li><a href="'+h(l.url)+'" target="_blank" rel="noopener">'+h(l.titulo||l.url)+'</a></li>'; }).join('')+'</ul></div>'); });
    if (extras.slides && extras.slides.length){
      var slidesSemPaginas = [];
      extras.slides.forEach(function(s){
        var sp = slideFlipbookPages(s);
        if (sp && sp.length) pages = pages.concat(sp); else slidesSemPaginas.push(s);
      });
      if (slidesSemPaginas.length) chunkList(slidesSemPaginas, 6).forEach(function(group){ pages.push('<div class="fp-page"><h3>Slides</h3><ul>'+group.map(function(s){ return s.url ? ('<li><a href="'+h(s.url)+'" target="_blank" rel="noopener">'+h(s.titulo||s.url)+'</a></li>') : ('<li>'+h(s.titulo||'Slides')+'</li>'); }).join('')+'</ul></div>'); });
    }
  }
  pages.push('<div class="fp-page fp-cover"><p class="muted">Fim</p></div>');
  return pages;
}
