function insertImageInTextEditor(){
  var input = getUploadInput();
  if (!input){ toast('Upload de imagem indisponível neste navegador.'); return; }
  input.onchange = function(e){
    var file = e.target.files && e.target.files[0];
    input.value = '';
    if (!file) return;
    if (!/^image\//.test(file.type)){ toast('Selecione um arquivo de imagem.'); return; }
    var reader = new FileReader();
    reader.onload = function(){
      var el = document.getElementById('txted-area');
      if (!el) return;
      el.focus();
      try { if (__LAST_RANGE){ var sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(__LAST_RANGE); } } catch(e2){}
      document.execCommand('insertHTML', false, '<img src="'+reader.result+'" style="max-width:100%;display:block;margin:10px 0;border-radius:8px">');
    };
    reader.onerror = function(){ toast('Não foi possível ler o arquivo.'); };
    reader.readAsDataURL(file);
  };
  input.click();
}
function lessonFlipbookData(courseId, mi, ai){
  var mods = effMods(courseId); var mod = mods[mi]; var a = mod.aulas[ai];
  var path = 'lessons.'+courseId+'.'+mi+'.'+ai;
  var titulo = ed(path+'.titulo', a.titulo);
  var content = ed(path+'.content', a.content||'');
  var primaryNormKey = (a.norms && a.norms[0]) ? a.norms[0] : null;
  var primaryNorm = primaryNormKey ? NORMS[primaryNormKey] : null;
  var trecho = primaryNorm ? ed('norms.'+primaryNormKey+'.trecho', primaryNorm.trecho||'') : '';
  var equip = primaryNormKey ? (ed('norms.'+primaryNormKey+'.equip', primaryNorm.equip)||[]) : [];
  var manuais = primaryNormKey ? (ed('norms.'+primaryNormKey+'.manuais', primaryNorm.manuais)||[]) : [];
  var images = [];
  var media = ed(path+'.media', a.media||{type:'none'});
  if (media && media.type==='image' && media.url) images.push({url:media.url, alt:media.alt||''});
  if (media && media.type==='pdf' && media.pages && media.pages.length){ media.pages.forEach(function(p){ images.push({url:p, alt:media.nome||'PDF'}); }); }
  if (primaryNormKey){
    var imgEquip = normImgEquip(primaryNormKey);
    if (imgEquip && imgEquip.url) images.push({url:imgEquip.url, alt:imgEquip.alt||''});
  }
  var extras = {videos: ed(path+'.videos', []), links: ed(path+'.links', []), slides: ed(path+'.slides', [])};
  var pages = buildFlipbookPages(titulo, mod.num+' · '+ed('modules.'+courseId+'.'+mi+'.titulo', mod.titulo), content, trecho, equip, manuais, images, extras);
  return {titulo:titulo, pages:pages};
}
function openLessonFlipbook(courseId, mi, ai){
  var d = lessonFlipbookData(courseId, mi, ai);
  logFlipbook(d.titulo, 'lesson', {courseId:courseId, mi:mi, ai:ai});
  openFlipbook(d.titulo, d.pages);
}
function downloadLessonFlipbook(courseId, mi, ai){
  var d = lessonFlipbookData(courseId, mi, ai);
  downloadFlipbookHtml(d.titulo, d.pages);
}
function normFlipbookData(key){
  var n = NORMS[key]; if (!n) return null;
  var titulo = ed('norms.'+key+'.titulo', n.titulo);
  var descricao = ed('norms.'+key+'.descricao', n.descricao||'');
  var trecho = ed('norms.'+key+'.trecho', n.trecho||'');
  var equip = ed('norms.'+key+'.equip', n.equip)||[];
  var manuais = ed('norms.'+key+'.manuais', n.manuais)||[];
  var images = [];
  var imgEquip = normImgEquip(key);
  if (imgEquip && imgEquip.url) images.push({url:imgEquip.url, alt:imgEquip.alt||''});
  var pages = buildFlipbookPages(titulo, n.code, descricao||trecho, trecho, equip, manuais, images);
  return {titulo:titulo, pages:pages};
}
function openNormFlipbook(key){
  var d = normFlipbookData(key); if (!d) return;
  logFlipbook(d.titulo, 'norm', {key:key});
  openFlipbook(d.titulo, d.pages);
}
function downloadNormFlipbook(key){
  var d = normFlipbookData(key); if (!d) return;
  downloadFlipbookHtml(d.titulo, d.pages);
}
function normExcerptFlipbookData(key){
  var n = NORMS[key]; if (!n) return null;
  var titulo = ed('norms.'+key+'.titulo', n.titulo);
  var trecho = ed('norms.'+key+'.trecho', n.trecho||'');
  var equip = ed('norms.'+key+'.equip', n.equip)||[];
  var manuais = ed('norms.'+key+'.manuais', n.manuais)||[];
  var lib = findLib(n.code);
  var trechosLib = (lib && lib.trechos) || [];
  var trechoFull = [trecho].concat(trechosLib).filter(Boolean).join('<br><br>');
  var images = [];
  var imgEquip = normImgEquip(key);
  if (imgEquip && imgEquip.url) images.push({url:imgEquip.url, alt:imgEquip.alt||''});
  var pages = buildFlipbookPages(n.code+' — Trecho', titulo, '', trechoFull, equip, manuais, images);
  return {titulo:n.code+' — trecho', pages:pages};
}
function openNormExcerptFlipbook(key){
  var d = normExcerptFlipbookData(key); if (!d) return;
  logFlipbook(d.titulo, 'norm-trecho', {key:key});
  openFlipbook(d.titulo, d.pages);
}
function downloadNormExcerptFlipbook(key){
  var d = normExcerptFlipbookData(key); if (!d) return;
  downloadFlipbookHtml(d.titulo, d.pages);
}

