  sarsat: {categoria:'nautica', code:'COSPAS-SARSAT', titulo:'Localização por Satélite em Emergência', orgao:'COSPAS-SARSAT', ed:'Programa vigente', item:'EPIRB/PLB', trecho:'Sistema internacional de satélites para detecção e localização de balizas de emergência (EPIRB, PLB, ELT).', link:'https://cospas-sarsat.int/en/', equip:['EPIRB','PLB pessoal'], manuais:[{nome:'COSPAS-SARSAT — Site Oficial',url:'https://cospas-sarsat.int/en/'}]},
  rbac135: {categoria:'aviacao', code:'RBAC 135', titulo:'Equipamentos de Emergência e Sobrevivência em Operações Offshore e Sobre Água', orgao:'ANAC (Brasil)', ed:'Emenda 13 (vigente desde 01/06/2023)', item:'Seções 135.80, 135.117, 135.165–135.183', trecho:'Regulamento brasileiro de aviação civil que exige, para voos de helicóptero sobre grandes extensões de água e operações offshore, equipamentos de flutuação, coletes salva-vidas, balsas, ELT, kit de primeiros socorros e instrução de pouso na água aos passageiros (Seção 135.167 e correlatas).', link:'https://pergamum.anac.gov.br/arquivos/RBAC135EMD13.pdf', equip:['Colete salva-vidas individual','Balsa/bote de emergência','Transmissor localizador de emergência (ELT)','Kit de sobrevivência e primeiros socorros'], manuais:[{nome:'ANAC — RBAC 135 (texto integral)',url:'https://pergamum.anac.gov.br/arquivos/RBAC135EMD13.pdf'}]},
  opito_std: {categoria:'opito', code:'OPITO Standards', titulo:'Biblioteca de Padrões de Treinamento (BOSIET, HUET, FOET e afins)', orgao:'OPITO', ed:'Biblioteca de normas vigente', item:'Oil and Gas / Marine', trecho:'Biblioteca oficial dos padrões de treinamento e avaliação da OPITO para segurança offshore, incluindo os cursos BOSIET (Basic Offshore Safety Induction and Emergency Training), HUET (Helicopter Underwater Escape Training) e FOET (Further Offshore Emergency Training).', link:'https://opito.com/standards-and-qualifications/industry-standards-library', equip:['EAPR aeronáutico (short-term air supply)','Colete salva-vidas aeronáutico','Simulador de escape de helicóptero submerso (HUET)'], manuais:[{nome:'OPITO — Industry Standards Library',url:'https://opito.com/standards-and-qualifications/industry-standards-library'}]},
  samu_sbv: {categoria:'socorros', code:'Protocolo SBV — SAMU 192', titulo:'Atendimento Pré-Hospitalar — Suporte Básico de Vida', orgao:'SAMU 192 / Secretaria Municipal de Saúde', ed:'Protocolo vigente (atualizado)', item:'Suporte Básico e Intermediário de Vida', trecho:'Protocolo brasileiro de atendimento pré-hospitalar baseado em PHTLS/AMLS/ACLS, incluindo manual de primeiros socorros para leigos até a chegada do socorro especializado.', link:'https://prefeitura.sp.gov.br/web/saude/w/servicos/emergencia_192/337530', equip:['Kit de primeiros socorros','Desfibrilador externo automático (DEA)','Maca e colar cervical'], manuais:[{nome:'SAMU 192 — Protocolos de Atendimento',url:'https://prefeitura.sp.gov.br/web/saude/w/servicos/emergencia_192/337530'}]},
